import { For, Show } from "solid-js";
import { Dynamic } from "solid-js/web";
import { uploads, removeUpload } from "../store/uploads.ts";
import "@material/web/chips/input-chip.js";
import { formatBytes } from "../lib/format.ts";

export function AttachmentChipStack() {
  return (
    <div
      style={{
        position: "fixed",
        bottom: "12px",
        right: "12px",
        display: "flex",
        "flex-direction": "column",
        gap: "6px",
        "z-index": 9000,
        "pointer-events": "none",
      }}
      data-testid="attachment-chip-stack"
    >
      <For each={Object.values(uploads)}>
        {(u) => {
          // % is live during "up"; guard total=0 (empty file) → 100.
          const pct = () => (u.bytes_total > 0 ? Math.round((u.bytes_sent / u.bytes_total) * 100) : 100);
          return (
            <div style={{ display: "flex", "flex-direction": "column", "align-items": "flex-end", gap: "3px", "pointer-events": "auto" }}>
              {/* Real md-input-chip: shape + state-layer + a11y + built-in remove ✕
                  (unifies dismiss across states; for err it's the existing affordance,
                  for uploading a cancel). Status (↑/✓/✗) → leading icon; the per-state
                  bg-tint folds into the glyph. md-input-chip is single-label so name +
                  live sent/total + % merge into the label. */}
              <Dynamic
                component="md-input-chip"
                data-testid="attachment-chip"
                data-state={u.state}
                label={
                  u.state === "up"
                    ? `${u.name} · ${formatBytes(u.bytes_sent)} / ${formatBytes(u.bytes_total)} · ${pct()}%`
                    : `${u.name} · ${formatBytes(u.bytes_total)}`
                }
                title={u.err ?? `${formatBytes(u.bytes_total)} — ${u.name}`}
                style={{ "pointer-events": "auto", "max-width": "300px" }}
                on:remove={() => removeUpload(u.id)}
              >
                <span slot="icon" aria-hidden="true">
                  {u.state === "up" ? "↑" : u.state === "ok" ? "✓" : "✗"}
                </span>
              </Dynamic>
              {/* Determinate progress track — only while uploading. */}
              <Show when={u.state === "up"}>
                <div style={{ width: "100%", height: "3px", "border-radius": "2px", background: "var(--md-sys-color-surface-container-highest)", overflow: "hidden" }}>
                  <div style={{ width: `${pct()}%`, height: "100%", background: "var(--md-sys-color-primary)", transition: "width 120ms var(--md-ease-standard)" }} />
                </div>
              </Show>
            </div>
          );
        }}
      </For>
    </div>
  );
}
