// filesRead RPC (worker reads its local file → coord relays bytes → here), so it
// works whether the session is on this Mac or another one on the tailnet.
// Wired to terminal file-link clicks (CellTerminal): Cmd/Ctrl-click a path in
// the terminal → the file downloads, instead of the in-app viewer that errored.

import { coordClient } from "../connect.ts";
import { addToast } from "./toastStore.ts";

/** Parse the internal `/file/<workerFp>/<enc path>[#L<n>]` href produced by
 *  CellTerminal's resolveFile back into { workerFp, absolute path }. */
export function parseFileHref(href: string): { workerFp: string; path: string } | null {
  const noHash = href.replace(/#L\d+$/, "");
  const m = noHash.match(/^\/file\/([^/]+)\/(.*)$/);
  if (!m) return null;
  const path = "/" + m[2].split("/").map(decodeURIComponent).join("/");
  return { workerFp: m[1], path };
}

/** Fetch a worker file's bytes and trigger a browser download of them. */
export async function downloadWorkerFileByHref(href: string): Promise<void> {
  const parsed = parseFileHref(href);
  if (!parsed) { addToast("Bad file link", "err"); return; }
  const name = parsed.path.split("/").pop() || "download";
  const clearProgress = addToast(`Downloading ${name}…`, "ok", { ttlMs: null });
  try {
    const res = await coordClient.filesRead({ workerFp: parsed.workerFp, path: parsed.path });
    // res.data is a fresh, tightly-backed Uint8Array from protobuf decode — a
    // valid BlobPart at runtime; the cast placates the DOM lib's tighter type.
    const url = URL.createObjectURL(new Blob([res.data as BlobPart]));
    const a = document.createElement("a");
    a.href = url;
    a.download = name;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    clearProgress();
  } catch (e) {
    clearProgress();
    addToast(`Download failed: ${e instanceof Error ? e.message : String(e)}`, "err");
  }
}
