  async filesReadChunk(req, ctx) {
    const caller = requireAuth(ctx.values);
    const sock = getWorkerHubSocket(req.workerFp);
    if (!sock) throw new ConnectError("worker not connected", Code.FailedPrecondition);
    const pending = createPendingRpc<{ content_b64: string; size: number; eof: boolean }>(30_000, req.workerFp);
    sendBrowserCmd(sock, caller, pending.request_id, {
      kind: "read-file-chunk", request_id: pending.request_id, path: req.path, offset: Number(req.offset), len: req.len,
    });
    const data = await pending.promise;
    const bytes = data.content_b64 ? Uint8Array.from(atob(data.content_b64), c => c.charCodeAt(0)) : new Uint8Array(0);
    return create(FilesReadChunkResponseSchema, { data: bytes, size: BigInt(data.size), eof: data.eof });
  },
  ```
- Add `attachmentProbe` (resolve worker from session like `attachFileChunk` L86–89, relay like `filesRead`):
  ```ts
  async attachmentProbe(req, ctx) {
    const caller = requireAuth(ctx.values);
    if (!req.sessionId) throw new ConnectError("session_id required", Code.InvalidArgument);
    const row = await deps.db.selectFrom("sessions").select(["worker_fp"]).where("id", "=", req.sessionId).executeTakeFirst();
    if (!row) throw new ConnectError("session not found", Code.NotFound);
    const sock = getWorkerHubSocket(row.worker_fp);
    if (!sock) throw new ConnectError("worker offline", Code.Unavailable);
    const pending = createPendingRpc<{ hit: boolean; abs_path: string }>(10_000, row.worker_fp);
    sendBrowserCmd(sock, caller, pending.request_id, {
      kind: "attachment-probe", request_id: pending.request_id, session_id: req.sessionId, sha256: req.sha256, short_path: req.shortPath,
    });
    const data = await pending.promise;
    return create(AttachmentProbeResponseSchema, { hit: data.hit, absPath: data.abs_path });
  },
  ```
No `router.ts` change: this file's handlers are spread into the single `router.service()` literal, so adding methods here satisfies the (now larger) `CoordinatorService` impl requirement.

### 4a. Web — unified transfer store + format helpers (`apps/web/src`) [independent of 4b]

**New `store/transfers.ts`** (supersedes `store/uploads.ts`). Module-level Solid store keyed by id; models both directions and computes speed/ETA. Non-reactive rate samples in a side `Map` to avoid store churn.
```ts
export type TransferDir = "up" | "down";
export type TransferState = "hashing" | "active" | "ok" | "err" | "dedup";
export interface Transfer {
  id: string; name: string; dir: TransferDir;
  bytes_done: number; bytes_total: number;   // total 0 = unknown (download pre-first-reply)
  speed: number;                              // bytes/sec, EMA; 0 = unknown
  eta_s: number;                              // seconds left; -1 = unknown
  state: TransferState; err?: string;
}
```
API:
- `addTransfer(t: { id; name; dir; bytes_total; state }): void` — seeds `bytes_done:0, speed:0, eta_s:-1`; records the first rate sample.
- `setTransferProgress(id: string, bytesDone: number, bytesTotal?: number, nowMs = performance.now()): void` — no-op if `!transfers[id]` (late callback after dismiss, per uploads.ts L30 pattern). EMA: with a prior sample and `dt = (now - prev.t)/1000 > 0.05`, `inst = (bytesDone - prev.bytes)/dt`, `speed = prev.speed>0 ? 0.4*inst + 0.6*prev.speed : inst`; `eta_s = speed>0 && total>0 ? max(0,(total-bytesDone)/speed) : -1`; write `{bytes_done, bytes_total, speed, eta_s}` and update the sample. If `dt <= 0.05`, write only `bytes_done`/`bytes_total` (accumulate the sample). The `nowMs` param exists solely so tests are deterministic.
- `markTransferState(id, state: TransferState, err?): void` — sets state (+err); for `"ok"` and `"dedup"` schedule `removeTransfer(id)` after 2000ms (matches upload success auto-dismiss, uploads.ts L37); `"err"` persists until dismissed; clears the rate sample.
- `removeTransfer(id): void` — delete store key + rate sample.
- Export `transfers`.

**`lib/format.ts`** — add (reuse existing `formatBytes`):
```ts
export function formatSpeed(bytesPerSec: number): string {
  if (!isFinite(bytesPerSec) || bytesPerSec <= 0) return "—";
  return `${formatBytes(bytesPerSec)}/s`;
}
export function formatEta(seconds: number): string {
  if (!isFinite(seconds) || seconds < 0) return "";
  if (seconds < 1) return "<1s";
  const s = Math.round(seconds), m = Math.floor(s / 60), h = Math.floor(m / 60);
  if (s < 60) return `${s}s`;
  if (m < 60) return s % 60 ? `${m}m ${s % 60}s` : `${m}m`;
  return m % 60 ? `${h}h ${m % 60}m` : `${h}h`;
}
```

### 4b. Web — unified M3 transfer card (`apps/web/src/components/TransferCard.tsx`, new) [independent of 4a's store internals, depends on its exports]

Replaces `AttachmentChip.tsx`. `Portal`-mounted fixed bottom-right stack (`z-index: 9000`, `pointer-events: none` on wrapper, `auto` on cards), `data-testid="transfer-stack"`, `<For each={Object.values(transfers)}>`. Each item is an M3 card styled like `PairRequestNotifier.tsx`'s `PairCard` (`--md-sys-color-surface-container-high` bg, `--md-sys-color-outline-variant` border, radius, subtle elevation), `data-testid="transfer-card"`, `data-state={t.state}`, `data-dir={t.dir}`, containing:
- Header row: a direction glyph (`t.dir === "up" ? "↑" : "↓"`), the filename (`text-overflow: ellipsis`, `max-width` ~260px), and a dismiss `md-icon-button` (✕) → `removeTransfer(t.id)` (cancel while active / dismiss when done or error).
- **Real M3 `md-linear-progress`** (the "proper design element"): `import "@material/web/progress/linear-progress.js"` in this file; add `"md-linear-progress": Record<string, unknown>` to `md-elements.d.ts`. Bind via properties (md reads props): `prop:value={t.bytes_total > 0 ? t.bytes_done / t.bytes_total : 0}` and `prop:indeterminate={t.state === "hashing" || (t.state === "active" && t.bytes_total === 0)}`. Hide the bar for terminal states `ok`/`dedup`/`err`.
- Meta line (small, `--md-sys-color-on-surface-variant`), by state:
  - `hashing` → `"Checking…"` (dedup pre-check; upload only).
  - `active` → `` `${formatBytes(bytes_done)} / ${formatBytes(bytes_total)} · ${pct}% · ${formatSpeed(speed)}` `` plus `` ` · ${formatEta(eta_s)} left` `` when `formatEta(eta_s)` is non-empty. `pct = bytes_total>0 ? round(bytes_done/bytes_total*100) : 0`.
  - `dedup` → `` `Already uploaded · reused` `` with an ✓ accent (`--color-ok`).
  - `ok` → `` `${t.dir === "up" ? "Uploaded" : "Downloaded"} · ${formatBytes(bytes_total)}` `` with ✓ (`--color-ok`).
  - `err` → `t.err` in `--color-err`, selectable text, persists.

### 5. Web — wire chunked download + dedup upload (depends on 3 + 4)

**5a. Upload dedup** — `lib/attachments.ts`:
- Add `const DEDUP_MAX_BYTES = 64 * 1024 * 1024;` and
  ```ts
  async function sha256Hex(file: File): Promise<string> {
    const digest = await crypto.subtle.digest("SHA-256", await file.arrayBuffer());
    return [...new Uint8Array(digest)].map(b => b.toString(16).padStart(2, "0")).join("");
  }
  ```
  (Pattern already used in `auth/web-key.ts` L121–124.)
- Rewrite `enqueueAttachment` to use the transfers store + best-effort probe:
  ```ts
  export async function enqueueAttachment(session: Session, file: File): Promise<void> {
    const id = crypto.randomUUID();
    addTransfer({ id, name: file.name, dir: "up", bytes_total: file.size, state: "hashing" });
    try {
      if (file.size > 0 && file.size <= DEDUP_MAX_BYTES) {
        try {
          const sha256 = await sha256Hex(file);
          const probe = await coordClient.attachmentProbe({ sessionId: session.id, sha256, size: BigInt(file.size), filename: file.name, shortPath: getShortPathPref() });
          if (probe.hit) {
            inputChannel.sendInput(session.id, new TextEncoder().encode(`${probe.absPath} `));
            markTransferState(id, "dedup");
            return;
          }
        } catch { /* probe is best-effort: fall through to a normal upload */ }
      }
      markTransferState(id, "active");
      const res = await uploadAttachment(session, file, (sent) => setTransferProgress(id, sent));
      inputChannel.sendInput(session.id, new TextEncoder().encode(`${res.abs_path} `));
      markTransferState(id, "ok");
    } catch (err) {
      markTransferState(id, "err", err instanceof Error ? err.message : String(err));
    }
  }
  ```
  Swap the import `../store/uploads.ts` → `../store/transfers.ts` (`addTransfer, setTransferProgress, markTransferState`). `uploadAttachment` itself is unchanged. Files `> DEDUP_MAX_BYTES` skip the probe and upload directly (hashing a multi-GB file in the browser would defeat the O(chunk) memory design); the worker still records their hash on save, so a later ≤cap re-upload of identical bytes still can't occur (size differs) — this is intentional and noted below.

**5b. Chunked download** — `lib/downloadWorkerFile.ts`: rewrite `downloadWorkerFileByHref` to loop `filesReadChunk` and drive the transfer card:
```ts
const DOWNLOAD_CHUNK = 4 * 1024 * 1024;
// ...parse href (unchanged); addToast("Bad file link","err") stays for the parse-failure case.
const id = crypto.randomUUID();
addTransfer({ id, name, dir: "down", bytes_total: 0, state: "active" });
try {
  const parts: BlobPart[] = [];
  let offset = 0, total = 0;
  for (;;) {
    const res = await coordClient.filesReadChunk({ workerFp: parsed.workerFp, path: parsed.path, offset: BigInt(offset), len: DOWNLOAD_CHUNK });
    total = Number(res.size);
    if (res.data.length) { parts.push(res.data as BlobPart); offset += res.data.length; }
    setTransferProgress(id, offset, total);
    if (res.eof || res.data.length === 0) break;   // eof, or defensive stop if a chunk returns nothing
  }
  const url = URL.createObjectURL(new Blob(parts));
  const a = document.createElement("a"); a.href = url; a.download = name;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  markTransferState(id, "ok");
} catch (e) {
  markTransferState(id, "err", e instanceof Error ? e.message : String(e));
}
```
Remove the `addToast("Downloading…")`/`clearProgress()` usage (card replaces it); keep the `addToast` import only for the bad-link case. Browser still assembles the whole `Blob` in memory (unavoidable for an `<a download>` without the File System Access API — same as the current unary path); the win is progress/speed/ETA and no 25 MB cap.

